-- SQL Dump de base de datos inicial de RegistraMe
-- Generado para poblar la base de datos de pruebas/producción

CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "cash" ("cajCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "cajNom" varchar(50) NOT NULL UNIQUE, "cajDes" varchar(200) NULL, "cajEstado" varchar(15) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "usuCod_id" integer NOT NULL REFERENCES "users_user" ("usuCod") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "cash_opening" ("cajaAperCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "cajaApertuFechHora" datetime NOT NULL, "cajaAperMontInicial" decimal NOT NULL, "cajaAperFechaHorCierre" datetime NULL, "cajaAperMontCierre" decimal NULL, "cajaAperMontEsperado" decimal NULL, "cajaAperDiferencia" decimal NULL, "cajaAperEstado" varchar(10) NOT NULL, "cajaAperObservacio" text NULL, "cajCod_id" integer NOT NULL REFERENCES "cash" ("cajCod") DEFERRABLE INITIALLY DEFERRED, "usuCod_id" integer NOT NULL REFERENCES "users_user" ("usuCod") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "categories_productcategory" ("catproCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "catproCode" varchar(5) NOT NULL UNIQUE, "catproNom" varchar(20) NOT NULL UNIQUE, "catproRequiereInventario" bool NOT NULL);
CREATE TABLE "clients_client" ("cliCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "cliNumDoc" varchar(20) NULL UNIQUE, "cliNomCompleto" varchar(100) NOT NULL, "cliTelef" varchar(9) NULL, "cliFechaNac" date NULL, "cliTipoDoc" varchar(10) NULL);
CREATE TABLE "clients_optometrist" ("optCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "optNombre" varchar(100) NOT NULL, "optApellido" varchar(100) NOT NULL);
CREATE TABLE "clients_recipe" ("recCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "recFech" date NOT NULL, "recEstado" varchar(50) NULL, "recObservaciones" text NULL, "recInfoExtra" text NULL, "receDIP" integer NULL, "receAdd" decimal NULL, "receEsfeOD" decimal NULL, "receCilinOD" decimal NULL, "receEjeOD" integer NULL, "receAvccOD" integer NULL, "receEsfeOI" decimal NULL, "receCilinOI" decimal NULL, "receEjeOI" integer NULL, "receAvccOI" integer NULL, "receEsExterna" bool NOT NULL, "diagnostico" text NOT NULL CHECK ((JSON_VALID("diagnostico") OR "diagnostico" IS NULL)), "cliCod_id" integer NOT NULL REFERENCES "clients_client" ("cliCod") DEFERRABLE INITIALLY DEFERRED, "optCod_id" integer NOT NULL REFERENCES "clients_optometrist" ("optCod") DEFERRABLE INITIALLY DEFERRED, "receDIPCerca" integer NULL);
CREATE TABLE "comprobante" ("comprCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "comprSerie" varchar(4) NOT NULL, "comprCorrelativo" integer NOT NULL, "comprFechaEmision" datetime NOT NULL, "comprNombreCliente" varchar(200) NOT NULL, "comprDocumentoCliente" varchar(50) NOT NULL, "comprSubtotal" decimal NOT NULL, "comprDescuento" decimal NOT NULL, "comprTotal" decimal NOT NULL, "comprAnulado" bool NOT NULL, "ventCod_id" integer NOT NULL UNIQUE REFERENCES "venta" ("ventCod") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "comprobante_detalle" ("comprDetCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "comprDetDescripcion" varchar(500) NOT NULL, "comprDetCantidad" integer NOT NULL, "comprDetPrecioUni" decimal NOT NULL, "comprDetSubtotal" decimal NOT NULL, "comprDetDescuento" decimal NOT NULL, "comprDetTotal" decimal NOT NULL, "comprCod_id" integer NOT NULL REFERENCES "comprobante" ("comprCod") DEFERRABLE INITIALLY DEFERRED, "prodCod_id" integer NOT NULL REFERENCES "product" ("prodCod") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "users_user" ("usuCod") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "luna_caracteristica" ("lunCarCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "lunCarDescripcion" text NOT NULL, "lunCarPrecioAdicional" decimal NOT NULL, "lunCarActivo" bool NOT NULL, "lunCarNombre" varchar(50) NOT NULL UNIQUE);
CREATE TABLE "luna_configuracion" ("lunConfCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "lunConfPrecioBase" decimal NOT NULL, "lunConfActivo" bool NOT NULL, "lunMatCod_id" integer NOT NULL REFERENCES "luna_material" ("lunMatCod") DEFERRABLE INITIALLY DEFERRED, "lunTipCod_id" integer NOT NULL REFERENCES "luna_tipo" ("lunTipCod") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "luna_material" ("lunMatCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "lunMatNombre" varchar(50) NOT NULL UNIQUE, "lunMatDescripcion" text NOT NULL, "lunMatActivo" bool NOT NULL);
CREATE TABLE "luna_tipo" ("lunTipCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "lunTipNombre" varchar(50) NOT NULL UNIQUE, "lunTipDescripcion" text NOT NULL, "lunTipActivo" bool NOT NULL);
CREATE TABLE "opticalCenter_opticalcenter" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "optNom" varchar(255) NOT NULL, "optLema" varchar(255) NULL, "optDir" text NULL, "optProv" text NULL, "optTel" varchar(15) NULL, "optLogo" varchar(100) NULL);
CREATE TABLE "product" ("prodCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "prodCode" varchar(20) NULL UNIQUE, "prodDescr" text NOT NULL, "prodMarca" varchar(50) NOT NULL, "prodMate" varchar(2) NOT NULL, "prodColor" varchar(30) NOT NULL, "prodTalla" varchar(20) NOT NULL, "prodGenero" varchar(10) NOT NULL, "prodCostoInv" decimal NOT NULL, "prodPrecioVenta" decimal NOT NULL, "prodStock" integer NOT NULL, "prodStockMin" integer NOT NULL, "prodEstado" varchar(10) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "catproCod_id" integer NOT NULL REFERENCES "categories_productcategory" ("catproCod") DEFERRABLE INITIALLY DEFERRED, "provCod_id" integer NOT NULL REFERENCES "suppliers_supplier" ("provCod") DEFERRABLE INITIALLY DEFERRED, "prodDescripcionAdicional" text NOT NULL, "prodForma" varchar(30) NOT NULL, "prodTieneSobrelente" bool NOT NULL);
CREATE TABLE "product_sequence" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "sequence_type" varchar(10) NOT NULL UNIQUE, "current_value" integer NOT NULL, "description" varchar(50) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "suppliers_supplier" ("provCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provRuc" varchar(11) NULL UNIQUE, "provRazSocial" varchar(255) NOT NULL, "provDirec" text NULL, "provEmail" varchar(254) NULL, "provCiu" varchar(100) NULL, "provEstado" varchar(10) NOT NULL, "provTele" varchar(9) NULL);
CREATE TABLE "users_role" ("rolCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rolNom" varchar(50) NOT NULL, "rolDes" varchar(50) NOT NULL, "rolEstado" varchar(20) NOT NULL, "rolNivel" integer NOT NULL);
CREATE TABLE "users_user" ("last_login" datetime NULL, "is_superuser" bool NOT NULL, "usuCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "usuNom" varchar(20) NOT NULL UNIQUE, "password" varchar(128) NOT NULL, "usuNombreCom" varchar(60) NOT NULL, "usuDNI" varchar(8) NOT NULL, "usuTel" varchar(9) NOT NULL, "usuEmail" varchar(254) NOT NULL UNIQUE, "usuEstado" bool NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL);
CREATE TABLE "users_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "users_user" ("usuCod") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "users_user_roles" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "users_user" ("usuCod") DEFERRABLE INITIALLY DEFERRED, "role_id" integer NOT NULL REFERENCES "users_role" ("rolCod") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "users_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "users_user" ("usuCod") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "venta" ("ventCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "ventFecha" datetime NOT NULL, "ventFechaEntrega" date NULL, "ventEstado" varchar(20) NOT NULL, "ventEstadoRecoj" varchar(20) NOT NULL, "ventSubTotal" decimal NOT NULL, "ventDescuento" decimal NOT NULL, "ventTotal" decimal NOT NULL, "ventAdelanto" decimal NOT NULL, "ventSaldo" decimal NOT NULL, "ventObservaciones" text NOT NULL, "ventAnulada" bool NOT NULL, "ventMotivoAnulacion" text NOT NULL, "ventReferenciaPago" varchar(50) NOT NULL, "ventTarjetaTipo" varchar(10) NOT NULL, "cajaAperCod_id" integer NULL REFERENCES "cash_opening" ("cajaAperCod") DEFERRABLE INITIALLY DEFERRED, "cliCod_id" integer NULL REFERENCES "clients_client" ("cliCod") DEFERRABLE INITIALLY DEFERRED, "usuCod_id" integer NOT NULL REFERENCES "users_user" ("usuCod") DEFERRABLE INITIALLY DEFERRED, "ventFormaPago" varchar(15) NOT NULL);
CREATE TABLE "venta_detalle" ("ventDetCod" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "ventDetCantidad" integer NOT NULL, "ventDetPrecioUni" decimal NULL, "ventDetSubtotal" decimal NOT NULL, "ventDetDescuento" decimal NOT NULL, "ventDetTotal" decimal NOT NULL, "ventDetAnulado" bool NOT NULL, "ventDetDescripcion" varchar(500) NOT NULL, "ventDetMarca" varchar(100) NOT NULL, "prodCod_id" integer NOT NULL REFERENCES "product" ("prodCod") DEFERRABLE INITIALLY DEFERRED, "ventCod_id" integer NOT NULL REFERENCES "venta" ("ventCod") DEFERRABLE INITIALLY DEFERRED, "esLunaPersonalizada" bool NOT NULL, "lunaCaracteristicas" text NOT NULL, "lunaCostoLaboratorio" decimal NULL, "lunaMaterial" varchar(50) NOT NULL, "lunaTipo" varchar(50) NOT NULL, "lunaLaboratorio_id" integer NULL REFERENCES "suppliers_supplier" ("provCod") DEFERRABLE INITIALLY DEFERRED);
